def compute_order_amount(on_hand_inventory, pipeline_orders):
    # Base inventory target
    base_target = 573.0937932210944  # OPT_PARAM: {"initial": 573.0937932210944, "min": 400.0, "max": 800.0, "type": "float"}

    # Pipeline volatility measurement parameters
    volatility_window = 4  # OPT_PARAM: {"initial": 4, "min": 2, "max": 6, "type": "int"}
    volatility_threshold = 0.4  # OPT_PARAM: {"initial": 0.4, "min": 0.1, "max": 2.0, "type": "float"}
    volatility_penalty = 0.5  # OPT_PARAM: {"initial": 0.5, "min": 0.0, "max": 0.9, "type": "float"}

    # Pipeline recency weighting (novel: hyperbolic decay)
    recency_decay = 0.7  # OPT_PARAM: {"initial": 0.7, "min": 0.0, "max": 0.95, "type": "float"}
    recency_exponent = 1.6366349201513601  # OPT_PARAM: {"initial": 1.6366349201513601, "min": 1.0, "max": 2.5, "type": "float"}

    # Order modulation based on coverage gap (novel: sigmoid response)
    sigmoid_steepness = 3.6833761609966382  # OPT_PARAM: {"initial": 3.6833761609966382, "min": 1.0, "max": 5.0, "type": "float"}
    sigmoid_midpoint = 0.8  # OPT_PARAM: {"initial": 0.8, "min": 0.4, "max": 1.8, "type": "float"}

    # Order constraints
    min_order = 10.0  # OPT_PARAM: {"initial": 10.0, "min": 5.0, "max": 30.0, "type": "float"}
    max_order = 95.78552014142252  # OPT_PARAM: {"initial": 95.78552014142252, "min": 80.0, "max": 200.0, "type": "float"}

    L = len(pipeline_orders)

    # NOVEL FEATURE 1: Hyperbolic recency-weighted pipeline
    # More recent pipeline orders get higher weight, but with hyperbolic decay
    # rather than exponential, giving smoother transition between weights
    recency_weighted_pipeline = 0.0
    for i, q in enumerate(pipeline_orders):
        # Hyperbolic decay: weight = recency_decay / (1 + recency_exponent * i)
        # This gives slower initial decay than exponential
        weight = recency_decay / (1.0 + recency_exponent * i)
        recency_weighted_pipeline += q * weight

    # NOVEL FEATURE 2: Pipeline volatility measurement
    # Measures variability in pipeline orders to detect unstable supply patterns
    if L >= volatility_window:
        # Calculate coefficient of variation of recent pipeline orders
        recent_orders = pipeline_orders[:volatility_window]
        mean_recent = sum(recent_orders) / volatility_window
        if mean_recent > 0:
            variance = sum((q - mean_recent) ** 2 for q in recent_orders) / volatility_window
            volatility = (variance ** 0.5) / mean_recent
        else:
            volatility = 0.0
    else:
        volatility = 0.0

    # Apply volatility penalty to target (novel decision logic)
    # High volatility reduces effective target to be more conservative
    if volatility > volatility_threshold:
        volatility_factor = 1.0 - volatility_penalty * (volatility - volatility_threshold)
        volatility_factor = max(0.5, volatility_factor)  # Cap the reduction
        adjusted_target = base_target * volatility_factor
    else:
        adjusted_target = base_target

    # Calculate effective inventory position
    effective_inventory = on_hand_inventory + recency_weighted_pipeline

    # Calculate coverage ratio
    coverage_ratio = effective_inventory / adjusted_target if adjusted_target > 0 else 1.0

    # NOVEL FEATURE 3: Sigmoid order response
    # Uses sigmoid function to smoothly transition between ordering regimes
    # based on coverage gap, avoiding sharp thresholds
    gap = 1.0 - coverage_ratio
    if gap > 0:
        # Sigmoid response: order_amount ∝ 1 / (1 + exp(-steepness*(gap-midpoint)))
        sigmoid_response = 1.0 / (1.0 + 2.71828 ** (-sigmoid_steepness * (gap - sigmoid_midpoint)))
        raw_order = gap * adjusted_target * sigmoid_response
    else:
        raw_order = 0.0

    # Apply order constraints
    if raw_order > 0:
        if raw_order < min_order:
            order_amount = 0
        elif raw_order > max_order:
            order_amount = max_order
        else:
            order_amount = raw_order
    else:
        order_amount = 0

    return order_amount
